def parse(s):
    parts = []
    i = 0
    while i < len(s):
        if s[i] == "{":
            j = s.index("}", i)
            parts.append(s[i + 1:j].split(","))
            i = j + 1
        else:
            parts.append([s[i]])
            i += 1
    return parts

def expand(parts, k, current, out):
    if k == len(parts):
        out.add(current)
        return
    for option in parts[k]:
        expand(parts, k + 1, current + option, out)

